CREATE TABLE shops(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),phone VARCHAR(30),email VARCHAR(190),status ENUM('active','inactive') DEFAULT 'active',wallet_balance DECIMAL(12,2) NOT NULL DEFAULT 0.00,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,shop_id INT NULL,name VARCHAR(150),email VARCHAR(190) UNIQUE,password VARCHAR(255),role ENUM('superadmin','shop_admin','staff','customer'),status ENUM('active','inactive') DEFAULT 'active',wallet_balance DECIMAL(12,2) NOT NULL DEFAULT 0.00,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(shop_id) REFERENCES shops(id) ON DELETE SET NULL);
CREATE TABLE customers(id INT AUTO_INCREMENT PRIMARY KEY,shop_id INT,name VARCHAR(150),mobile VARCHAR(20),email VARCHAR(190),pan VARCHAR(20),dob DATE,address TEXT,credit_score INT NULL,credit_report_json LONGTEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(shop_id) REFERENCES shops(id));
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,shop_id INT,name VARCHAR(180),brand VARCHAR(100),model VARCHAR(100),sku VARCHAR(80),category VARCHAR(80),selling_price DECIMAL(12,2),stock INT DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',FOREIGN KEY(shop_id) REFERENCES shops(id));
CREATE TABLE finance_rules(id INT AUTO_INCREMENT PRIMARY KEY,shop_id INT,min_score INT,max_score INT,interest_rate DECIMAL(7,3),max_finance DECIMAL(12,2),max_tenure INT,down_payment_percent DECIMAL(7,3),processing_fee DECIMAL(10,2),FOREIGN KEY(shop_id) REFERENCES shops(id));
CREATE TABLE credit_checks(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT,provider VARCHAR(80),reference_no VARCHAR(120),score INT,request_json LONGTEXT,response_json LONGTEXT,consent TINYINT(1),checked_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(checked_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE finance_applications(id INT AUTO_INCREMENT PRIMARY KEY,application_no VARCHAR(50) UNIQUE,shop_id INT,customer_id INT,product_id INT NULL,product_price DECIMAL(12,2),down_payment DECIMAL(12,2),finance_amount DECIMAL(12,2),interest_rate DECIMAL(7,3),tenure INT,emi DECIMAL(12,2),total_interest DECIMAL(12,2),processing_fee DECIMAL(10,2),total_payable DECIMAL(12,2),status VARCHAR(30) DEFAULT 'pending',created_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(shop_id) REFERENCES shops(id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE emi_schedules(id INT AUTO_INCREMENT PRIMARY KEY,finance_id INT,installment_no INT,due_date DATE,principal DECIMAL(12,2),interest DECIMAL(12,2),amount DECIMAL(12,2),paid_amount DECIMAL(12,2) DEFAULT 0,status VARCHAR(30) DEFAULT 'upcoming',paid_at DATETIME NULL,FOREIGN KEY(finance_id) REFERENCES finance_applications(id) ON DELETE CASCADE);
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,finance_id INT,emi_id INT NULL,customer_id INT,amount DECIMAL(12,2),payment_method VARCHAR(40),reference_no VARCHAR(100),remarks TEXT,paid_at DATETIME DEFAULT CURRENT_TIMESTAMP,recorded_by INT,FOREIGN KEY(finance_id) REFERENCES finance_applications(id),FOREIGN KEY(emi_id) REFERENCES emi_schedules(id) ON DELETE SET NULL,FOREIGN KEY(customer_id) REFERENCES customers(id));
CREATE TABLE documents(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT,finance_id INT NULL,type VARCHAR(60),file_path VARCHAR(255),status VARCHAR(30) DEFAULT 'uploaded',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(finance_id) REFERENCES finance_applications(id) ON DELETE SET NULL);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,title VARCHAR(180),message TEXT,is_read TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(120),module VARCHAR(80),description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE wallet_transactions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,shop_id INT NULL,txnid VARCHAR(100) UNIQUE NOT NULL,payu_mihpayid VARCHAR(100) NULL,amount DECIMAL(12,2) NOT NULL,type ENUM('credit','debit') DEFAULT 'credit',status ENUM('pending','success','failed') DEFAULT 'pending',payment_gateway VARCHAR(50) DEFAULT 'PayU',payment_mode VARCHAR(50) NULL,hash VARCHAR(255) NULL,remarks VARCHAR(255) NULL,response_json LONGTEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
